package com.cyberpath.learning;
import android.app.PendingIntent;
import android.appwidget.*;
import android.content.*;
import android.widget.RemoteViews;
import android.view.View;
import org.json.*;
import java.time.LocalDate;
public final class LearningWidget extends AppWidgetProvider {
 private static final String CYCLE="com.cyberpath.learning.WIDGET_CYCLE";
 public static void updateAll(Context c){PersonalReminderWidget.updateAll(c);synchronized(AppFiles.LOCK){AppWidgetManager manager=AppWidgetManager.getInstance(c);for(int id:manager.getAppWidgetIds(new ComponentName(c,LearningWidget.class)))update(c,manager,id);}}
 private static void update(Context c,AppWidgetManager manager,int id){
  if(AppLock.enabled(c)){RemoteViews locked=new RemoteViews(c.getPackageName(),R.layout.learning_widget);locked.setTextViewText(R.id.widget_course,"Your studio is locked");locked.setTextViewText(R.id.widget_topic,"Unlock LW to see your next task");locked.setTextViewText(R.id.widget_progress_text,"Private on this device");locked.setTextViewText(R.id.widget_continue,"Open LW");locked.setViewVisibility(R.id.widget_cycle,View.GONE);locked.setViewVisibility(R.id.widget_progress,View.GONE);PendingIntent open=PendingIntent.getActivity(c,id,new Intent(c,MainActivity.class).putExtra("lwRoute","work"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);locked.setOnClickPendingIntent(R.id.widget_root,open);locked.setOnClickPendingIntent(R.id.widget_continue,open);manager.updateAppWidget(id,locked);return;}
  JSONObject workspace=AppFiles.workspace(c);String chosen=NativeServices.prefs(c).getString("widgetCourse-"+id,"active");JSONObject course=NativeServices.selectedCourse(workspace,chosen);String courseId=course.optString("id",""),title=course.optString("title","LW Learning Studio"),topic=course.optString("nextTask",course.optString("nextTopic","Open the app to choose your next topic"));int percent=course.optInt("percent",0),today=0;try{JSONArray tasks=workspace.getJSONObject("courses").getJSONObject(courseId).getJSONObject("days").getJSONObject(LocalDate.now().toString()).getJSONArray("tasks");for(int i=0;i<tasks.length();i++)if(tasks.getJSONObject(i).optBoolean("done"))today++;}catch(Exception ignored){}
  JSONObject learning=workspace.optJSONObject("learning"),upgrades=learning==null?null:learning.optJSONObject("upgrades");String mode=upgrades==null?"next":upgrades.optString("widgetMode","next"),route="work",action="Continue →",progressText=percent+"% of course tasks · "+today+" tasks today";boolean quickNote=false;
  if("daily".equals(mode)){route="day";title="Today's learning";int minutes=0,done=0,goal=learning.optInt("dailyMinutes",90);JSONObject courses=workspace.optJSONObject("courses");if(courses!=null){java.util.Iterator<String> keys=courses.keys();while(keys.hasNext()){JSONObject state=courses.optJSONObject(keys.next());if(state==null)continue;JSONArray sessions=state.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject session=sessions.optJSONObject(i);if(session!=null&&LocalDate.now().toString().equals(session.optString("date")))minutes+=session.optInt("minutes");}JSONObject days=state.optJSONObject("days"),day=days==null?null:days.optJSONObject(LocalDate.now().toString());JSONArray tasks=day==null?null:day.optJSONArray("tasks");if(tasks!=null)for(int i=0;i<tasks.length();i++)if(tasks.optJSONObject(i)!=null&&tasks.optJSONObject(i).optBoolean("done"))done++;}}topic=minutes+" / "+goal+" minutes";percent=goal>0?Math.min(100,minutes*100/goal):0;progressText=done+" tasks completed today";action="Open plan →";}
  else if("notes".equals(mode)){route="notebook";quickNote=true;title="Quick notes";topic="Capture your next idea";JSONArray pages=learning.optJSONArray("pages");String newest="";if(pages!=null)for(int i=0;i<pages.length();i++){JSONObject page=pages.optJSONObject(i);if(page!=null&&!page.optBoolean("trashed")&&page.optString("updatedAt").compareTo(newest)>0){newest=page.optString("updatedAt");topic=page.optString("title","Untitled");}}percent=0;progressText="Saved offline on this device";action="New note →";}
  RemoteViews views=new RemoteViews(c.getPackageName(),R.layout.learning_widget);views.setTextViewText(R.id.widget_course,title);views.setTextViewText(R.id.widget_topic,topic);views.setTextViewText(R.id.widget_progress_text,progressText);views.setTextViewText(R.id.widget_continue,action);views.setContentDescription(R.id.widget_continue,action);views.setViewVisibility(R.id.widget_cycle,"next".equals(mode)?View.VISIBLE:View.GONE);views.setViewVisibility(R.id.widget_progress,"notes".equals(mode)?View.GONE:View.VISIBLE);views.setProgressBar(R.id.widget_progress,100,percent,false);PendingIntent open;
  if("work".equals(route))open=NativeServices.openWork(c,courseId,id*2+500);else{Intent target=new Intent(c,MainActivity.class).putExtra("lwRoute",route).putExtra("lwQuickNote",quickNote).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);open=PendingIntent.getActivity(c,id*2+500,target,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
  views.setOnClickPendingIntent(R.id.widget_root,open);views.setOnClickPendingIntent(R.id.widget_continue,open);Intent cycle=new Intent(c,LearningWidget.class).setAction(CYCLE).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);views.setOnClickPendingIntent(R.id.widget_cycle,PendingIntent.getBroadcast(c,id,cycle,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));manager.updateAppWidget(id,views);
 }
 @Override public void onUpdate(Context c,AppWidgetManager manager,int[] ids){for(int id:ids)update(c,manager,id);}
 @Override public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(CYCLE.equals(intent.getAction())){int widget=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);if(widget<0)return;JSONObject summary=AppFiles.workspace(c).optJSONObject("companionData");JSONArray courses=summary==null?null:summary.optJSONArray("courses");if(courses==null||courses.length()==0)return;String current=NativeServices.selectedCourse(c,NativeServices.prefs(c).getString("widgetCourse-"+widget,"active")).optString("id");int next=0;for(int i=0;i<courses.length();i++)if(current.equals(courses.optJSONObject(i).optString("id")))next=(i+1)%courses.length();NativeServices.prefs(c).edit().putString("widgetCourse-"+widget,courses.optJSONObject(next).optString("id")).apply();update(c,AppWidgetManager.getInstance(c),widget);}}
 @Override public void onDeleted(Context c,int[] ids){for(int id:ids)NativeServices.prefs(c).edit().remove("widgetCourse-"+id).apply();}
}
